@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800&family=DM+Mono:wght@400;500&display=swap');
:root{color-scheme:dark;--cream:#e9e4d7;--rust:#d77e55;--muted:#8b9290;--panel:rgba(13,17,17,.83)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#090c0c;color:var(--cream);font-family:'Barlow Condensed',sans-serif;touch-action:none}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{position:absolute;inset:0;pointer-events:none;opacity:.1;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E");mix-blend-mode:screen}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 38%,rgba(0,0,0,.26) 70%,rgba(0,0,0,.8) 130%)}#hud{position:absolute;inset:0;display:none;pointer-events:none}.topline{position:absolute;top:max(22px,env(safe-area-inset-top));left:clamp(18px,4vw,60px);right:clamp(18px,4vw,60px);display:flex;justify-content:space-between;align-items:flex-start}.brand,.eyebrow,.stamp,.controls,.radio,.tiny{font-family:'DM Mono',monospace;font-size:10px;letter-spacing:.13em;color:#aab1ad}.chapter{font-size:22px;font-weight:600;letter-spacing:.08em;margin-top:3px}.radio{padding:9px 13px;border:1px solid #57605b;background:#0d1210aa}.dot{display:inline-block;background:#d18b66;width:6px;height:6px;border-radius:50%;margin-right:5px;box-shadow:0 0 9px #e58b60}.objective{position:absolute;top:max(84px,calc(env(safe-area-inset-top) + 60px));left:clamp(18px,4vw,60px);max-width:275px;background:linear-gradient(90deg,rgba(8,12,12,.83),transparent);padding:11px 24px 12px 14px;border-left:2px solid var(--rust)}.eyebrow{font-size:9px;letter-spacing:.18em;color:#9da6a0}.objective #objective{font-size:19px;letter-spacing:.035em;margin:4px 0 1px}.objective #subobjective{font:10px 'DM Mono',monospace;color:#9ca29e}.bottom{position:absolute;bottom:max(28px,env(safe-area-inset-bottom));left:clamp(18px,4vw,60px);right:clamp(18px,4vw,60px);display:flex;align-items:flex-end;justify-content:space-between}.vitals,.ammo{width:178px;padding:12px 14px;background:var(--panel);border:1px solid #35403a;backdrop-filter:blur(8px)}.health{height:5px;background:#303431;margin-top:9px}.health i{display:block;width:100%;height:100%;background:#c27957;transition:width .2s}.vitalrow{font:12px 'DM Mono',monospace;margin-top:6px}.sep{color:#657069;padding:0 5px}.ammo{width:210px}.tiny{font-size:8px;color:#818a84;margin-left:5px}.ammorow{display:flex;align-items:baseline;gap:8px;margin-top:1px}.ammorow b{font-size:34px;font-weight:500}.ammorow span{font:12px 'DM Mono',monospace;color:#a8afa8}.ammorow .reload{margin-left:auto;font-size:9px}.toast{position:absolute;top:24%;left:50%;transform:translate(-50%,-10px);font:11px 'DM Mono',monospace;letter-spacing:.16em;color:#e3c9ad;padding:11px 17px;border-top:1px solid #c17a57;border-bottom:1px solid #c17a57;background:#101512dd;opacity:0;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.crosshair{position:absolute;width:24px;height:24px;border:1px solid #e8dfd3a8;border-radius:50%;transform:translate(-50%,-50%);display:none}.crosshair i,.crosshair b{position:absolute;background:#e8dfd3a8}.crosshair i{width:1px;height:34px;left:11px;top:-6px}.crosshair b{height:1px;width:34px;top:11px;left:-6px}
.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,#090e0ddc,#0a0f0eb8 45%,#090e0d77)}.introCard{width:min(510px,90vw);padding:clamp(22px,5vh,48px);background:linear-gradient(145deg,#111715ed,#111715d9);border:1px solid #435048;box-shadow:0 25px 100px #000b;position:relative}.introCard:before,.introCard:after{content:'';position:absolute;width:26px;height:26px;border-color:#c77d59}.introCard:before{top:-1px;left:-1px;border-top:2px solid;border-left:2px solid}.introCard:after{bottom:-1px;right:-1px;border-bottom:2px solid;border-right:2px solid}.stamp{font-size:9px;color:#c98c6d}.title{font-size:clamp(44px,9vw,76px);line-height:.77;font-weight:800;letter-spacing:.02em;margin:24px 0}.title em{font-style:normal;color:#cb7957}.rule{width:100%;height:1px;background:linear-gradient(90deg,#c77957,transparent);margin:23px 0}.story{font-size:18px;line-height:1.35;color:#c2c8c0;margin:0 0 21px}.mission{display:flex;gap:14px;align-items:center;margin:20px 0 24px}.mission>span{font:19px 'DM Mono',monospace;color:#c77957}.mission b,.mission small{display:block;letter-spacing:.08em}.mission b{font-size:14px}.mission small{font-size:13px;color:#959f98;margin-top:2px}button{font-family:inherit;color:var(--cream);cursor:pointer}#start,#again{width:100%;height:49px;border:0;background:#b96849;font-size:17px;font-weight:700;letter-spacing:.15em;text-align:left;padding:0 16px;box-shadow:0 5px 20px #0005}#start span,#again span{float:right;font-size:21px}.controls{text-align:center;font-size:8px;line-height:1.8;color:#89928b;margin-top:16px}.hidden{display:none!important}.chapterCard{position:absolute;top:42%;left:50%;transform:translate(-50%,-50%);text-align:center;display:none;text-shadow:0 3px 20px #000}.chapterCard.show{display:grid;gap:5px;animation:card 3.2s forwards}.chapterCard small{font:10px 'DM Mono',monospace;letter-spacing:.2em;color:#d18a67}.chapterCard b{font-size:40px;letter-spacing:.08em}.chapterCard span{font-size:14px;color:#c2c6bd}@keyframes card{0%{opacity:0;transform:translate(-50%,-35%)}15%{opacity:1;transform:translate(-50%,-50%)}75%{opacity:1}100%{opacity:0}}#touch{display:none;pointer-events:none}#touch button,#stick{pointer-events:auto;position:absolute;bottom:max(24px,env(safe-area-inset-bottom));user-select:none;-webkit-user-select:none}#stick{width:122px;height:122px;left:20px}.stickRing{position:absolute;inset:8px;border:1px solid #d7d9d044;border-radius:50%;background:#11181355;box-shadow:inset 0 0 20px #0005}#nub{position:absolute;width:47px;height:47px;left:37px;top:37px;border:1px solid #d7ddd888;border-radius:50%;background:#c6c7b52b;box-shadow:0 3px 9px #0007}#fire{right:25px;width:82px;height:82px;border-radius:50%;bottom:max(34px,env(safe-area-inset-bottom));background:#a7503d88;border:1px solid #e4ad8caa;font:11px 'DM Mono',monospace;letter-spacing:.15em}#heal,#reloadBtn{right:117px;width:43px;height:43px;border-radius:50%;background:#101612aa;border:1px solid #aeb9af77;font-size:19px}#heal{bottom:max(105px,calc(env(safe-area-inset-bottom) + 105px));color:#d39a78}#reloadBtn{bottom:max(44px,calc(env(safe-area-inset-bottom) + 44px))}
@media (pointer:coarse),(max-width:700px){#touch{display:block}.bottom{bottom:max(190px,calc(env(safe-area-inset-bottom) + 174px));left:18px;right:18px;justify-content:flex-end;gap:8px}.vitals,.ammo{width:128px;padding:9px}.ammo{width:143px}.brand{font-size:8px}.chapter{font-size:17px}.radio{font-size:8px;padding:7px}.objective{top:76px;max-width:230px}.objective #objective{font-size:16px}.reload{display:none}.controls{font-size:7px}.crosshair{display:block}.introCard{padding:25px 24px}.title{font-size:clamp(47px,12vw,66px);margin:19px 0}.story{font-size:16px}.chapterCard b{font-size:32px}}
@media (max-height:520px) and (orientation:landscape){.bottom{bottom:14px}.vitals,.ammo{padding:7px 10px}.objective{top:65px}.introCard{padding:17px 26px}.title{font-size:48px;margin:12px 0}.rule{margin:14px 0}.story{font-size:15px;margin-bottom:10px}.mission{margin:10px 0}.controls{margin-top:8px}}

(()=>{
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d'),$=s=>document.querySelector(s);let W,H,D,started=false,ended=false,last=0,clock=0,toastTimer=0;
const chapters=[{name:'CHAPTER I — THE LOW ROAD',tag:'CHAPTER I',title:'THE LOW ROAD',line:'The forest is listening.',objective:'Reach the old relay station',radio:'CARRIER LOST',count:3},{name:'CHAPTER II — THE HOLLOW',tag:'CHAPTER II',title:'THE HOLLOW',line:'Someone is answering from below.',objective:'Find the survey team',radio:'VOICE DETECTED',count:4},{name:'CHAPTER III — LAST LIGHT',tag:'CHAPTER III',title:'LAST LIGHT',line:'One last transmission.',objective:'Transmit the warning',radio:'SIGNAL LOCKED',count:5}];
let player,enemies=[],bullets=[],particles=[],decor=[],rain=[],stage=0,kills=0,shot=0,reloadTimer=0,spawned=0,fireHeld=false,keys={},mouse={x:0,y:0,down:false},joy={x:0,y:0},aim={x:0,y:-1},damageFlash=0,shake=0;
const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
function resize(){D=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*D;canvas.height=H*D;ctx.setTransform(D,0,0,D,0,0);seedDecor()}
function seedDecor(){decor=[];let seed=98123;const r=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};for(let i=0;i<240;i++){let x=(r()-.5)*3800,y=(r()-.5)*3300;if(Math.abs(x-y*.18)<100)continue;let type=r()<.7?'tree':r()<.86?'rock':'shack';decor.push({x,y,type,size:type==='tree'?rand(18,42):rand(15,35),tone:r()})}rain=Array.from({length:130},()=>({x:rand(0,innerWidth),y:rand(0,innerHeight),v:rand(280,620),l:rand(8,19),a:rand(.08,.27)}))}
function reset(){player={x:0,y:0,hp:100,ammo:12,reserve:60,med:2,angle:-Math.PI/2,step:0,invuln:0};enemies=[];bullets=[];particles=[];stage=0;kills=0;spawned=0;ended=false;startStage();$('#ending').classList.add('hidden');$('#hud').style.display='block';$('#intro').style.display='none';showCard()}
function startStage(){let c=chapters[stage];spawned=0;let n=c.count;for(let i=0;i<n;i++){let a=Math.PI*2*i/n+rand(-.4,.4),d=rand(260,410);enemies.push({x:player.x+Math.cos(a)*d,y:player.y+Math.sin(a)*d,hp:2,speed:rand(24,34),attack:rand(.3,1),hit:0,phase:rand(0,6),alive:true})}spawned=n;$('#chapter').textContent=c.name;$('#radio').textContent=c.radio;$('#objective').textContent=c.objective;updateSub();showCard()}
function showCard(){let c=chapters[stage];$('#cardtag').textContent=c.tag;$('#cardtitle').textContent=c.title;$('#cardline').textContent=c.line;let el=$('#chapterCard');el.classList.remove('show');void el.offsetWidth;el.classList.add('show')}
function toast(t){let e=$('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2100)}
function updateSub(){let left=enemies.filter(e=>e.alive).length;if(left)$('#subobjective').textContent=`Neutralize the hostiles · ${chapters[stage].count-left} / ${chapters[stage].count}`;else $('#subobjective').textContent=`Move to the marked point · ${Math.round(dist(player,target())/10)} m`}
function target(){return stage===0?{x:0,y:-440}:stage===1?{x:390,y:-790}:{x:850,y:-1140}}
function begin(){reset()}
function moveAxis(){let x=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+joy.x,y=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0)+joy.y,l=Math.hypot(x,y);if(l>1){x/=l;y/=l}return{x,y}}
function fire(){if(!started||ended||reloadTimer>0||player.ammo<=0)return;if(clock-shot<.24)return;shot=clock;player.ammo--;updateAmmo();let candidates=enemies.filter(e=>e.alive).sort((a,b)=>dist(player,a)-dist(player,b));let hit=null;for(let e of candidates){let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-player.angle),Math.cos(Math.atan2(dy,dx)-player.angle));if(d<550&&Math.abs(diff)<(isTouch()?0.8:0.22)){hit=e;break}}
let end=hit?{x:hit.x,y:hit.y}:{x:player.x+Math.cos(player.angle)*430,y:player.y+Math.sin(player.angle)*430};bullets.push({x:player.x+Math.cos(player.angle)*16,y:player.y+Math.sin(player.angle)*16,x2:end.x,y2:end.y,t:.11});if(hit){hit.hp--;hit.hit=.16;hit.x+=Math.cos(player.angle)*9;hit.y+=Math.sin(player.angle)*9;burst(hit.x,hit.y,'#b9755b',5);if(hit.hp<=0){hit.alive=false;kills++;burst(hit.x,hit.y,'#d0a079',12);updateSub();if(enemies.every(e=>!e.alive))toast('THE PATH IS CLEAR. FIND THE SIGNAL.')}}else burst(end.x,end.y,'#e4d7b6',2);shake=3}
function updateAmmo(){$('#ammo').textContent=player.ammo;$('#reserve').textContent=player.reserve;$('#healthbar').style.width=player.hp+'%';$('#healthtxt').textContent=player.hp;$('#medtxt').textContent='✚ '+player.med}
function reload(){if(player.ammo===12||!player.reserve||reloadTimer>0)return;reloadTimer=1.05;$('#reload').textContent='RELOADING…';setTimeout(()=>$('#reload').textContent='R RELOAD',1100)}
function heal(){if(player.med&&player.hp<100){player.med--;player.hp=Math.min(100,player.hp+38);updateAmmo();toast('FIELD DRESSING APPLIED')}}
function burst(x,y,color,n){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(20,130);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:rand(.2,.6),max:.6,color})}}
function isTouch(){return matchMedia('(pointer:coarse)').matches||W<700}
function update(dt){clock+=dt;player.invuln=Math.max(0,player.invuln-dt);let m=moveAxis();player.x+=m.x*150*dt;player.y+=m.y*150*dt;if(m.x||m.y){player.angle=Math.atan2(m.y,m.x);player.step+=dt*10}if(mouse.down&&!isTouch()){let sx=W/2,sy=H*.56;player.angle=Math.atan2(mouse.y-sy,mouse.x-sx);fire()}if(fireHeld)fire();if(reloadTimer>0){reloadTimer-=dt;if(reloadTimer<=0){let take=Math.min(12-player.ammo,player.reserve);player.ammo+=take;player.reserve-=take;updateAmmo()}}
for(let e of enemies){if(!e.alive)continue;e.phase+=dt;let dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>28){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt}e.attack-=dt;if(d<35&&e.attack<=0&&player.invuln<=0){e.attack=1.15;player.hp=Math.max(0,player.hp-9);player.invuln=.45;damageFlash=.3;shake=8;updateAmmo();if(player.hp<=0)gameOver()}}
for(let b of bullets)b.t-=dt;bullets=bullets.filter(b=>b.t>0);for(let p of particles){p.x+=p.vx*dt;p.y+=p.vy*dt;p.life-=dt;p.vx*=.96;p.vy*=.96}particles=particles.filter(p=>p.life>0);damageFlash=Math.max(0,damageFlash-dt);shake=Math.max(0,shake-dt*18);
if(enemies.every(e=>!e.alive)&&dist(player,target())<70){if(stage<2){stage++;player.ammo=Math.min(12,player.ammo+4);player.reserve+=12;player.med=Math.min(3,player.med+1);updateAmmo();startStage();toast('SUPPLY CACHE FOUND · +4 ROUNDS')}else win()}
updateSub();for(let r of rain){r.y+=r.v*dt;r.x-=r.v*.23*dt;if(r.y>H+20){r.y=-20;r.x=rand(0,W)}}}
function gameOver(){ended=true;$('#endingText').textContent='Mara never made it back to the coast. At dawn, the relay began broadcasting again—this time in the voice of someone else.';$('#finalCount').textContent=String(kills).padStart(2,'0');$('#ending').classList.remove('hidden')}
function win(){ended=true;$('#endingText').textContent='The warning gets through. As the coast guard answers, the voice on the relay whispers, “You came back.” Mara cuts the line. In the distance, a second tower lights up across the water.';$('#finalCount').textContent=String(kills).padStart(2,'0');$('#ending').classList.remove('hidden')}

