function win(){ended=true;$('#endingText').textContent='The warning gets through. As the coast guard answers, the voice on the relay whispers, “You came back.” Mara cuts the line. In the distance, a second tower lights up across the water.';$('#finalCount').textContent=String(kills).padStart(2,'0');$('#ending').classList.remove('hidden')}
function pathPoint(y){return{x:Math.sin(y*.0017)*210+Math.sin(y*.004)*65,y}}
function world(){let cx=player.x-W/2,cy=player.y-H*.56;ctx.save();ctx.translate(-cx,-cy);let grad=ctx.createRadialGradient(player.x,player.y,80,player.x,player.y,850);grad.addColorStop(0,'#343c32');grad.addColorStop(.55,'#252e29');grad.addColorStop(1,'#111a19');ctx.fillStyle=grad;ctx.fillRect(cx-10,cy-10,W+20,H+20);
// Mud road winding through the trees
ctx.lineCap='round';ctx.beginPath();for(let y=player.y-1700;y<player.y+1700;y+=22){let p=pathPoint(y);if(y===player.y-1700)ctx.moveTo(p.x,y);else ctx.lineTo(p.x,y)}ctx.strokeStyle='#36372e';ctx.lineWidth=106;ctx.stroke();ctx.strokeStyle='#484538';ctx.lineWidth=82;ctx.stroke();ctx.strokeStyle='#54503e';ctx.lineWidth=2;ctx.setLineDash([3,18]);ctx.stroke();ctx.setLineDash([]);
for(let o of decor){if(Math.abs(o.x-player.x)>W*.8+100||Math.abs(o.y-player.y)>H*.8+100)continue;drawProp(o)}
// Relay marker
let t=target();ctx.save();ctx.translate(t.x,t.y);let pulse=(Math.sin(clock*3)+1)/2;ctx.strokeStyle=`rgba(218,142,99,${.35+pulse*.45})`;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,24+pulse*5,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#dd9669';ctx.beginPath();ctx.arc(0,-35,4,0,Math.PI*2);ctx.fill();ctx.restore();
for(let e of enemies)if(e.alive)drawEnemy(e);drawPlayer();for(let b of bullets){ctx.strokeStyle=`rgba(255,230,177,${Math.min(1,b.t*13)})`;ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(b.x2,b.y2);ctx.stroke()}for(let p of particles){ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,2.1,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;ctx.restore()}
function drawProp(o){let {x,y,size:s,type}=o;ctx.save();ctx.translate(x,y);if(type==='tree'){ctx.fillStyle='#111815';ctx.beginPath();ctx.ellipse(6,9,s*.95,s*.7,0,0,7);ctx.fill();ctx.fillStyle=o.tone>.5?'#202923':'#1b241f';ctx.beginPath();ctx.arc(0,0,s,0,7);ctx.fill();ctx.fillStyle='#394035';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(-s*.23,-s*.2,s*.52,0,7);ctx.fill();ctx.globalAlpha=1;ctx.fillStyle='#5e5036';ctx.fillRect(-2,-2,4,8)}else if(type==='rock'){ctx.fillStyle='#151a18';ctx.beginPath();ctx.ellipse(3,5,s*1.1,s*.68,0,0,7);ctx.fill();ctx.fillStyle='#515147';ctx.beginPath();ctx.moveTo(-s,-s*.3);ctx.lineTo(-s*.4,-s);ctx.lineTo(s*.65,-s*.7);ctx.lineTo(s,s*.2);ctx.lineTo(s*.3,s*.75);ctx.lineTo(-s*.8,s*.55);ctx.closePath();ctx.fill()}else{ctx.fillStyle='#151816';ctx.fillRect(-s-2,4,s*2+4,s*1.3);ctx.fillStyle='#55463a';ctx.fillRect(-s,-s*.4,s*2,s*1.3);ctx.fillStyle='#292a24';ctx.beginPath();ctx.moveTo(-s-5,-s*.4);ctx.lineTo(0,-s*1.1);ctx.lineTo(s+5,-s*.4);ctx.fill();ctx.fillStyle='#151615';ctx.fillRect(-4,0,8,s*.9);ctx.fillStyle='#aa754f';ctx.globalAlpha=.8;ctx.fillRect(s*.42,-s*.03,4,4)}ctx.restore()}
